import { Router } from 'express';
import { authRouter } from './v1/auth.js';
import { ordersRouter } from './v1/orders.js';
import { platformRouter } from './v1/platform.js';
import { restaurantRouter } from './v1/restaurants.js';
import { vapiRouter } from './v1/vapi.js';
import { stripeWebhookRouter } from './webhooks/stripe.js';
import { squareWebhookRouter } from './webhooks/square.js';
import { cloverWebhookRouter } from './webhooks/clover.js';
import { posRouter } from './v1/pos.js';
import { vapiToolsRouter } from './v1/vapi-tools.js';
import { vapiAssistantRouter } from './v1/vapi-assistant.js';
import { onboardingRouter } from './v1/onboarding.js';
import { supportRouter } from './v1/support.js';
export const router = Router();
router.use('/onboarding', onboardingRouter);
router.use('/auth', authRouter);
router.use('/platform', platformRouter);
router.use('/restaurants', restaurantRouter);
router.use('/orders', ordersRouter);
router.use('/support', supportRouter);
router.use('/webhooks/vapi', vapiRouter);
router.use('/webhooks/stripe', stripeWebhookRouter);
router.use('/webhooks/square', squareWebhookRouter);
router.use('/webhooks/clover', cloverWebhookRouter);
router.use('/pos', posRouter);
router.use('/vapi/tools', vapiToolsRouter);
router.use('/vapi', vapiAssistantRouter);
